"In this page, the Home Assistant blocks use a <b>sample house</b>, so you can build and test safely. Change a state below (press Enter) to try your 'when … changes' scripts. Exported Python connects to your real Home Assistant: set HA_URL and HA_TOKEN (a long-lived access token from your Home Assistant profile, under Security).":"𐀁𐀚 𐀵𐀵 𐀆𐀵, Home Assistant 𐀠𐀪𐀵 𐀐𐀨𐀃𐀲𐀂 <b>𐀞𐀨𐀆𐀓𐀔 𐀈𐀗</b>, 𐀃𐀞 𐀀𐀭𐀞𐀩𐀃 𐀃𐀂𐀒𐀈𐀕𐀁 𐀏𐀂 𐀟𐀂𐀨𐀁𐀁 𐀉𐀙𐀭𐀂. 𐀀𐀨𐀏𐀮 𐀏𐀲𐀭𐀲𐀯 𐀏𐀵 (𐀠𐀁𐀮 Enter) 𐀟𐀂𐀨𐀁𐀁 𐀮𐀨 𐀰 “𐀃𐀳 … 𐀀𐀨𐀏𐀮𐀲𐀂”. Python 𐀁𐀏𐀕𐀜 𐀆𐀁𐀲𐀂 𐀁𐀚 𐀀𐀩𐀳 Home Assistant 𐀰: 𐀳𐀮 HA_URL 𐀏𐀂 HA_TOKEN (𐀔𐀏𐀫𐀠𐀍 access token 𐀀𐀢 Home Assistant profile 𐀰, 𐀄𐀡 Security).",
