"The <b>Model</b> menu is your primary model: it does every step. If it fails on a step (no key, out of credit, service down or unreachable), the first backup answers that step instead, then the second, then the third. The run log says each time a backup steps in.":"<b>𐀶𐀡</b> menu 𐀁𐀯 𐀓𐀪𐀍 𐀶𐀡 𐀰: 𐀡𐀁𐀂 𐀞𐀲 𐀡𐀅. 𐀁 𐀀𐀔𐀲𐀚𐀂 𐀁𐀚 𐀡𐀆 (𐀃𐀄𐀆 𐀏𐀨𐀹, 𐀃𐀄𐀆 𐀓𐀬𐀰, 𐀴𐀪𐀠𐀊 𐀟𐀟𐀵𐀒 𐀁 𐀀𐀠𐀐𐀵), 𐀡𐀫𐀵 𐀁𐀠𐀓𐀫 𐀀𐀡𐀑𐀪𐀚𐀲𐀂 𐀵𐀵 𐀡𐀆 𐀀𐀴 𐀀𐀵, 𐀀𐀠 𐀆𐀄𐀳𐀫, 𐀀𐀠 𐀴𐀪𐀵. 𐀞𐀨𐀑𐀯 𐀆𐀵 𐀩𐀐𐀂 𐀁𐀏𐀲 𐀃𐀳 𐀁𐀠𐀓𐀫 𐀁𐀮𐀞𐀂𐀚𐀂.",
