"The sample house has no entity called “{id}”. Open the Home Assistant panel to see the ones it has.":"𐀞𐀨𐀆𐀓𐀔 𐀈𐀗 𐀃𐀄𐀆 𐀐𐀩𐀔 𐀁𐀐𐀂 𐀃𐀜𐀔 “{id}”. 𐀀𐀜𐀂𐀐 Home Assistant 𐀠𐀙𐀒 𐀃𐀨𐀁 𐀀 𐀁𐀐𐀂.",
