"There's no saved program called “{name}”. Save it from the Programs button first.":"𐀃𐀄𐀆 𐀰𐀿𐀕𐀜 𐀡𐀫𐀏𐀨𐀔 𐀃𐀜𐀔𐀽𐀲𐀂 “{name}”. 𐀰𐀽 𐀀𐀵 𐀡𐀫𐀵 𐀀𐀢 𐀒𐀡 𐀡𐀫𐀏𐀨𐀔𐀲.",
