"This page can't open other websites, so the agent is told to use search_web instead. Exported Python reads the page for real.":"𐀵𐀵 𐀆𐀵 𐀃𐀄 𐀀𐀜𐀂𐀐 𐀀𐀨 𐀇𐀓𐀶𐀃 𐀵𐀡, 𐀃𐀄𐀵 𐀁𐀠𐀵𐀫𐀡 𐀐𐀩𐀄𐀲𐀂 𐀐𐀨𐀁𐀁 search_web. Python 𐀁𐀏𐀕𐀜 𐀀𐀩𐀳 𐀀𐀙𐀑𐀜𐀐 𐀆𐀵.",
"This page can't open {u}, so it only has its sample feeds: {feeds}. Exported Python reads any feed.":"𐀵𐀵 𐀆𐀵 𐀃𐀄 𐀀𐀜𐀂𐀐 {u}, 𐀃𐀄𐀵 𐀗𐀜 𐀁𐀐𐀂 𐀞𐀨𐀆𐀓𐀔 𐀫𐀁: {feeds}. Python 𐀁𐀏𐀕𐀜 𐀀𐀙𐀑𐀜𐀐 𐀞𐀲 𐀫𐀁.",
"This page uses a sample house, so nothing real is read or switched. Export to Python to use your own Home Assistant.":"𐀵𐀵 𐀆𐀵 𐀐𐀨𐀲𐀂 𐀞𐀨𐀆𐀓𐀔 𐀈𐀗, 𐀃𐀄𐀵 𐀃𐀄𐀆 𐀀𐀩𐀳 𐀀𐀙𐀑𐀜𐀐𐀲𐀂 𐀁 𐀀𐀨𐀏𐀮𐀲𐀂. 𐀁𐀏𐀐𐀐 𐀁𐀚 Python 𐀐𐀨𐀁𐀁 𐀰 Home Assistant.",
"This page uses sample {noun}, so nothing real is read or sent. Exported Python uses your own.":"𐀵𐀵 𐀆𐀵 𐀐𐀨𐀲𐀂 𐀞𐀨𐀆𐀓𐀔𐀲 ({noun}), 𐀃𐀄𐀵 𐀃𐀄𐀆 𐀀𐀩𐀳 𐀀𐀙𐀑𐀜𐀐𐀲𐀂 𐀁 𐀟𐀟𐀲𐀂. Python 𐀁𐀏𐀕𐀜 𐀐𐀨𐀲𐀂 𐀰.",
