"This run stops before a Claude call once it has used about {budget} tokens (about {used} so far).":"𐀀𐀆 𐀞𐀨𐀑𐀯 𐀞𐀄𐀁𐀲𐀂 𐀡𐀫 𐀏𐀩𐀯 Claude 𐀃𐀳 𐀐𐀨𐀵 𐀟𐀪 {budget} tokens (𐀟𐀪 {used} 𐀕𐀑 𐀝).",
