"To change a list, put a list variable in the 'in list' slot.":"𐀀𐀨𐀏𐀮𐀁 𐀏𐀲𐀫𐀒, 𐀴𐀳𐀐 𐀏𐀲𐀫𐀒 𐀀𐀫𐀍𐀵 𐀁𐀚 𐀃𐀞 “𐀁𐀚 𐀏𐀲𐀫𐀒”.",
