"  Type y or n.":"  ka-ra-pe na-i e o-u.",
"'let me choose from' got an empty list.":"“e-a me ke-re-ke-e a-pu” ke-no ka-ta-ro-ko e-ra-pe.",
"'{key} of' needs a record in its second slot.":"“{key} a-pu” de-i ka-ra-pe e-ne de-u-te-ro o-pa.",
"(Page watcher: {url} has no readable words; it may need a browser to show them. It's checked again each time.)":"(de-to pu-ra-ka: {url} o-u-de e-pe-a a-na-ki-no-ta e-ke-i; du-na-ta-i di-ku-tu-o-se-ko-po de-i de-i-ke-e. e-ka-ta pa-ra-ki-si a-pi e-ke-ta-ze-ta-i.)",
"(Page watcher: {url} has nothing with “{words}” in it right now. It's checked again each time.)":"(de-to pu-ra-ka: {url} nu o-u-de e-ke-i me-ta “{words}”. e-ka-ta pa-ra-ki-si a-pi e-ke-ta-ze-ta-i.)",
