"This program uses Gemini. Install its package first:  pip install google-genai":"to-to po-ro-ka-ra-ma ke-ra-ta-i Gemini. po-ro-to ka-ta-se-te ke-ne-a:  pip install google-genai",
"This program uses Home Assistant. Put HA_URL (for example http://homeassistant.local:8123) and HA_TOKEN (a long-lived access token from your Home Assistant profile, Security tab) {where_keys}.":"to-to po-ro-ka-ra-ma ke-ra-ta-i Home Assistant. ti-te-ke HA_URL (o-u-to http://homeassistant.local:8123) ka-i HA_TOKEN (ma-ka-ro-pi-jo access token a-pu Home Assistant profile so, Security tab) {where_keys}.",
"This program uses {provider}. Put {key_env} = your-key {where_keys} ({signup}).":"to-to po-ro-ka-ra-ma ke-ra-ta-i {provider}. ti-te-ke {key_env} = ka-ra-wi-so {where_keys} ({signup}).",
"This run stops before a model call once it has used {x} tokens (used so far: {x2}).":"a-de pa-ra-ki-si pa-u-e-ta-i po-ro ka-re-si tu-po o-te ke-ra-to {x} tokens (ke-ra-me-na me-ki nu: {x2}).",
