"“{kind}” isn't a type the agent knows. Use text, number, yes/no, list or any (for “{name}”).":"“{kind}” o-u-ka ke-no o e-pi-to-ro-po wo-i-de. ke-ra text, number, yes/no, list e any (u-pe-re “{name}”).",
"“{name}” can't run while other scripts are running at the same time. Run it from a script that runs on its own (not alongside a broadcast).":"“{name}” o-u ka-ra-e-ta-i o-pe-ra a-ra se-ra a-ma ka-ra-o-si. ka-ra-e a-to a-pu se-ra o mo-no ka-ra-e-i (o-u me-ta ke-ru-ka).",
"“{repo}” isn't a GitHub project. Use owner/name, like octocat/hello-world.":"“{repo}” o-u-ka GitHub we-ko. ke-ra owner/name, o-u-to octocat/hello-world.",
